// Auto-generated companion for Strings.resx. This file would normally be
// regenerated by Visual Studio's ResXFileCodeGenerator; we keep a hand-written
// copy so the build doesn't depend on the IDE. The two resx files (Strings.resx
// = Russian fallback, Strings.en.resx = English) are loaded at runtime by
// WPF based on the current UI culture; this class exposes the Russian values
// as compile-time constants via x:Static.
//
// To add a new string: add <data name="..."> in BOTH .resx files with the same
// name (Russian in Strings.resx, English in Strings.en.resx), then add a
// matching property here.

#nullable enable
using System.Globalization;
using System.Resources;
using System.Threading;

namespace VRify.App.Resources;

internal static class Strings
{
    private static ResourceManager? _rm;

    private static ResourceManager RM => _rm ??= new ResourceManager(
        typeof(Strings).FullName!, typeof(Strings).Assembly);

    /// <summary>Apply the user's language preference (ru/en/auto) to the current thread.</summary>
    public static void ApplyCulture(string? lang)
    {
        CultureInfo ci = lang switch
        {
            "ru" => new CultureInfo("ru-RU"),
            "en" => new CultureInfo("en-US"),
            _    => CultureInfo.CurrentUICulture,   // auto: follow the OS
        };
        Thread.CurrentThread.CurrentUICulture = ci;
        CultureInfo.DefaultThreadCurrentUICulture = ci;
    }

    private static string Get(string name) => RM.GetString(name, Thread.CurrentThread.CurrentUICulture) ?? name;

    // Window
